/*
 * Build the app-wide menu based on the current state.
 *  Note: the Window and Help menus are generated by Swift, then injected in. Windows-equivalent menus still need to be added.
 */

import {
  Menu,
  MenuItem,
  PredefinedMenuItem,
  Submenu,
} from "@tauri-apps/api/menu";
import { emit } from "@tauri-apps/api/event";
import { platform as getPlatform } from "@tauri-apps/plugin-os";
import { setMenu } from "./setMenu";
import {
  menuItem,
  checkMenuItem,
  beginShortcuts,
  commitShortcuts,
} from "./menuShortcuts";
import { WindowType } from "../typings";

// Builds run one at a time: shortcuts are recorded as items are created (see
// menuShortcuts.ts), so overlapping builds would mix up each other's
let buildQueue: Promise<void> = Promise.resolve();

export function buildMenu(
  windowType: WindowType,
  recentFiles: string[] = []
): Promise<void> {
  buildQueue = buildQueue
    .then(() => buildMenuNow(windowType, recentFiles))
    .catch((error) => console.error("Couldn't build the menu:", error));
  return buildQueue;
}

/*
 * Create items with menuItem/checkMenuItem (not MenuItem.new/CheckMenuItem.new)
 * so their accelerators also work on Windows (see menuShortcuts.ts).
 */
async function buildMenuNow(windowType: WindowType, recentFiles: string[]) {
  const platform = getPlatform();
  beginShortcuts();

  /*
   * App menu
   */
  const appSubmenu = await Submenu.new({
    text: "Choicelab",
    id: "app_submenu",
    items: [
      await menuItem({
        id: "about",
        text: "About Choicelab",
      }),
      await menuItem({
        id: "check_for_updates",
        text: "Check for Updates...",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await PredefinedMenuItem.new({
        item: "Services",
      }),
      await PredefinedMenuItem.new({
        text: "",
        item: "Separator",
      }),
      await PredefinedMenuItem.new({
        text: "Hide Choicelab",
        item: "Hide",
      }),
      await PredefinedMenuItem.new({
        item: "HideOthers",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "request-quit",
        text: "Quit Choicelab",
        accelerator: "CmdOrCtrl+Q",
      }),
    ],
  });

  /*
   * File menu — Open Recent submenu
   */

  const recentItems: Array<MenuItem | PredefinedMenuItem> = [];
  if (recentFiles.length === 0) {
    recentItems.push(
      await menuItem({
        id: "open_recent_no_items",
        text: "No Recent Projects",
        enabled: false,
      })
    );
  } else {
    for (let i = 0; i < recentFiles.length; i++) {
      const filePath = recentFiles[i];
      const name =
        filePath
          .split(/[/\\]/)
          .pop()
          ?.replace(/\.clx$/i, "") ?? filePath;
      recentItems.push(
        await menuItem({ id: `open_recent_${i}`, text: name })
      );
    }
    recentItems.push(await PredefinedMenuItem.new({ item: "Separator" }));
    recentItems.push(
      await menuItem({ id: "clear_recent", text: "Clear Menu" })
    );
  }

  const openRecentSubmenu = await Submenu.new({
    text: "Open Recent",
    id: "open_recent_submenu",
    items: recentItems,
  });

  /*
   * File menu
   */

  const fileSubmenu = await Submenu.new({
    text: "File",
    id: "file_submenu",
    items: [
      await menuItem({
        id: "new_project",
        text: "New...",
        accelerator: "CmdOrCtrl+Shift+N",
      }),
      await menuItem({
        id: "open_project",
        text: "Open...",
        accelerator: "CmdOrCtrl+O",
      }),
      openRecentSubmenu,
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        text: "Save",
        id: "save",
        accelerator: "CmdOrCtrl+S",
        enabled: false,
      }),
      await menuItem({
        text: "Save As...",
        id: "save_as",
        accelerator: "Shift+CmdOrCtrl+S",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        text: "Export for Web...",
        id: "export",
        accelerator: "CmdOrCtrl+E",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await PredefinedMenuItem.new({
        text: "Close Window",
        item: "CloseWindow",
      }),
    ],
  });

  /*
   * Edit menu
   */

  const editSubmenu = await Submenu.new({
    text: "Edit",
    id: "edit_submenu",
    items: [
      await menuItem({
        text: "Undo",
        id: "undo",
        accelerator: "CmdOrCtrl+Z",
        enabled: false,
      }),
      await menuItem({
        text: "Redo",
        id: "redo",
        accelerator: "CmdOrCtrl+Shift+Z",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await PredefinedMenuItem.new({
        item: "Cut",
      }),
      await PredefinedMenuItem.new({
        item: "Copy",
      }),
      await PredefinedMenuItem.new({
        item: "Paste",
      }),
      await PredefinedMenuItem.new({
        item: "SelectAll",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        text: "Insert Variable",
        id: "insert_variable",
        enabled: false,
      }),
    ],
  });

  /*
   * View menu
   */

  const viewSubmenu = await Submenu.new({
    text: "View",
    id: "view_submenu",
    items: [
      await checkMenuItem({
        id: "show_node_editor",
        text: "Show Node Editor",
        enabled: false,
        accelerator: "CmdOrCtrl+R",
      }),
      await checkMenuItem({
        id: "show_variables",
        text: "Show Variables",
        enabled: false,
        accelerator: "CmdOrCtrl+T",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "toggle_preview",
        text: "Toggle Preview",
        accelerator: "CmdOrCtrl+G",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
    ],
  });

  /*
   * Project menu
   */

  const projectSubmenu = await Submenu.new({
    text: "Project",
    id: "project_submenu",
    items: [
      await menuItem({
        id: "new_cell",
        text: "New Cell",
        enabled: false,
        accelerator: "CmdOrCtrl+N",
      }),
      await menuItem({
        id: "new_branch",
        text: "New Branch",
        enabled: false,
        accelerator: "CmdOrCtrl+B",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "add_stem",
        text: "Add Branch Stem",
        enabled: false,
      }),
      // On macOS, this is turned into an alternate of "Add Branch Stem" that
      // shows while holding Option (see addNativeMenus in NativeBridge.m)
      await menuItem({
        id: "add_no_match_stem",
        text: "Add No-Match Stem",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "set_link",
        text: "Set Link",
        enabled: false,
        accelerator: "CmdOrCtrl+L",
      }),
      await menuItem({
        id: "disconnect_link",
        text: "Disconnect Link",
        enabled: false,
        accelerator: "CmdOrCtrl+D",
      }),
      await menuItem({
        id: "autofill",
        text: "Autofill Variables",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "open_in_browser",
        text: "Open Preview in Browser",
        enabled: false,
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "delete_nodes",
        text: "Delete Node",
        enabled: false,
        accelerator:
          platform === "macos" ? "CmdOrCtrl+Backspace" : "CmdOrCtrl+Delete",
      }),
      await menuItem({
        id: "delete_stem",
        text: "Delete Branch Stem",
        enabled: false,
        accelerator:
          platform === "macos"
            ? "CmdOrCtrl+Option+Backspace"
            : "CmdOrCtrl+Shift+Delete",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "project_settings",
        text: "Project Settings...",
        enabled: false,
        accelerator: "CmdOrControl+Shift+,",
      }),
    ],
  });

  /*
   * Window submenu, to be handled by Tauri once functionality is available (see below)
   *
  const windowSubmenu = await Submenu.new({
    text: "Window",
    id: "window_submenu",
  });
  */

  const helpSubmenu = await Submenu.new({
    text: "Help",
    id: "help_submenu",
    items: [
      await menuItem({
        id: "open_help",
        text: "Choicelab Help",
      }),
      await menuItem({
        id: "report_issue",
        text: "Report Issue or Request Feature...",
      }),
      await PredefinedMenuItem.new({
        item: "Separator",
      }),
      await menuItem({
        id: "open_choicelab_site",
        text: "Website",
      }),
      await menuItem({
        id: "open_license",
        text: "License",
      }),
      await menuItem({
        id: "open_whatsNew",
        text: "Release Notes",
      }),
      await menuItem({
        id: "open_repo",
        text: "GitHub Repository",
      }),
      await menuItem({
        id: "open_acknowledgments",
        text: "Acknowledgments",
      }),
      // On macOS, this is in the app menu instead
      ...(platform === "macos"
        ? []
        : [
            await PredefinedMenuItem.new({ item: "Separator" }),
            await menuItem({
              id: "check_for_updates",
              text: "Check for Updates...",
            }),
            await menuItem({
              id: "about",
              text: "About Choicelab",
            }),
          ]),
    ],
  });

  /*
   * Set the menu
   */
  let menu: Menu | null = null;
  switch (platform) {
    case "windows":
    case "linux":
      // On Windows and Linux, only show the menu in project windows
      if (windowType === "project") {
        const items = [
          fileSubmenu,
          editSubmenu,
          viewSubmenu,
          projectSubmenu,
          helpSubmenu,
        ];
        menu = await Menu.new({ items: items });
        // Wait for the menu to be attached, so setMenu below can find it
        await menu.setAsWindowMenu();
      }
      break;
    case "macos":
      const items = [
        appSubmenu,
        fileSubmenu,
        editSubmenu,
        viewSubmenu,
        projectSubmenu,
        // windowSubmenu,
        // helpSubmenu,
      ];
      menu = await Menu.new({ items: items });
      // await windowSubmenu.setAsWindowsMenuForNSApp();
      // await helpSubmenu.setAsHelpMenuForNSApp();
      // Wait for the menu to be installed, so setMenu below updates it
      // rather than the menu it replaces
      await menu.setAsAppMenu();
      emit("add-native-menus");
      break;
  }
  await commitShortcuts(menu);
  if (menu === null) return;
  setMenu(windowType);
}
